//! Budget and profile-resolution rules E0028..E0034.

use std::collections::{BTreeMap, BTreeSet};

use super::diagnostic::{
    Diagnostic, Severity, err, err_with_hint, layer_err_with_hint, layer_seg_err_with_hint,
};
use crate::config::{Config, HeapCategory, Layer, MemoryProfile, Scenario, SegmentKind, SizeOrAuto};
use crate::error::ErrorCode;

pub(super) fn check_profile_resolution(
    cfg: &Config,
    scenario_name: &str,
    scen: &Scenario,
    out: &mut Vec<Diagnostic>,
) {
    let Some(prof_name) = scen.memory_profile.as_ref() else {
        return;
    };
    let Some(profile) = cfg.memory_profiles.get(prof_name) else {
        out.push(err_with_hint(
            ErrorCode(31),
            format!(
                "scenario `{scenario_name}` references undeclared memory_profile `{prof_name}`"
            ),
            format!("declare [memory_profiles.{prof_name}] or pick another profile"),
        ));
        return;
    };
    check_profile_partitions(prof_name, profile, out);
    check_layer_claims_match_profile(cfg, scen, profile, out);
}

fn check_profile_partitions(prof_name: &str, profile: &MemoryProfile, out: &mut Vec<Diagnostic>) {
    let mut ranges: Vec<(String, u32, u32)> = Vec::new();
    for p in &profile.partitions {
        let (Ok(base), Ok(size)) = (p.base.as_u32(), p.size.as_u32()) else {
            continue;
        };
        ranges.push((p.name.clone(), base, base.saturating_add(size)));
    }
    ranges.sort_by_key(|r| r.1);
    for w in ranges.windows(2) {
        if w[1].1 < w[0].2 {
            out.push(err(
                ErrorCode(33),
                format!(
                    "memory_profile `{prof_name}` partitions `{}` and `{}` overlap",
                    w[0].0, w[1].0
                ),
            ));
        }
    }
}

fn check_layer_claims_match_profile(
    cfg: &Config,
    scen: &Scenario,
    profile: &MemoryProfile,
    out: &mut Vec<Diagnostic>,
) {
    let mut available: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    for p in &profile.partitions {
        let regs: BTreeSet<&str> = p.regions.iter().map(|r| r.name.as_str()).collect();
        available.insert(p.name.as_str(), regs);
    }
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        if layer.absolute_addresses {
            continue;
        }
        for seg in &layer.segments {
            for claim in &seg.claims {
                let (Some(part), Some(region)) = (&claim.partition, &claim.region) else {
                    continue;
                };
                let ok = available
                    .get(part.as_str())
                    .map(|rs| rs.contains(region.as_str()))
                    .unwrap_or(false);
                if !ok {
                    out.push(layer_seg_err_with_hint(
                        ErrorCode(32),
                        layer_name,
                        seg.name.as_deref(),
                        format!("claim ({part}, {region}) not in profile partitions/regions"),
                        format!("available: {available:?}"),
                    ));
                }
            }
        }
    }
}

pub(super) fn check_oversized_heaps_need_justification(
    cfg: &Config,
    scen: &Scenario,
    out: &mut Vec<Diagnostic>,
) {
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        let layer_heap = layer_heap_size(layer);
        if layer_heap > 32 * 1024 && layer.heap_justification.is_none() {
            out.push(layer_err_with_hint(
                ErrorCode(30),
                layer_name,
                format!(
                    "layer claims heap > 32 KiB ({layer_heap} bytes) without heap_justification"
                ),
                "add [layers.<n>.heap_justification] with category + note".into(),
            ));
        }
        if let Some(j) = &layer.heap_justification
            && matches!(
                j.category,
                HeapCategory::DeadLeak | HeapCategory::AlgorithmicBloat
