13	pub(super) fn check_profile_resolution(
14	    cfg: &Config,
15	    scenario_name: &str,
16	    scen: &Scenario,
17	    out: &mut Vec<Diagnostic>,
18	) {
19	    let Some(prof_name) = scen.memory_profile.as_ref() else {
20	        return;
21	    };
22	    let Some(profile) = cfg.memory_profiles.get(prof_name) else {
23	        out.push(err_with_hint(
