36	fn check_profile_partitions(prof_name: &str, profile: &MemoryProfile, out: &mut Vec<Diagnostic>) {
37	    let mut ranges: Vec<(String, u32, u32)> = Vec::new();
38	    for p in &profile.partitions {
39	        let (Ok(base), Ok(size)) = (p.base.as_u32(), p.size.as_u32()) else {
40	            continue;
41	        };
42	        ranges.push((p.name.clone(), base, base.saturating_add(size)));
43	    }
44	    ranges.sort_by_key(|r| r.1);
45	    for w in ranges.windows(2) {
46	        if w[1].1 < w[0].2 {
47	            out.push(err(
48	                ErrorCode(33),
49	                format!(
50	                    "memory_profile `{prof_name}` partitions `{}` and `{}` overlap",
51	                    w[0].0, w[1].0
52	                ),
53	            ));
54	        }
55	    }
56	}
