112	                layer_name,
113	                format!(
114	                    "layer claims heap > 32 KiB ({layer_heap} bytes) without heap_justification"
115	                ),
116	                "add [layers.<n>.heap_justification] with category + note".into(),
117	            ));
118	        }
119	        if let Some(j) = &layer.heap_justification
120	            && matches!(
121	                j.category,
122	                HeapCategory::DeadLeak | HeapCategory::AlgorithmicBloat
123	            )
124	        {
125	            out.push(Diagnostic {
126	                code: ErrorCode(30),
127	                severity: Severity::Warning,
128	                layer: Some(layer_name.clone()),
129	                segment: None,
130	                message: format!(
131	                    "heap_justification.category = {:?}; --strict will reject",
