140	pub(super) fn check_heap_budgets(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
141	    let Some(prof_name) = scen.memory_profile.as_ref() else {
142	        return;
143	    };
144	    let Some(profile) = cfg.memory_profiles.get(prof_name) else {
145	        return;
146	    };
147	    let Some(budget) = profile.budget.as_ref() else {
148	        return;
149	    };
150	    let Ok(budget_max) = budget.heap_max.as_u32() else {
151	        return;
152	    };
153	    let bm = u64::from(budget_max);
154	    let mut heap_total: u64 = 0;
155	    for layer_name in &scen.layers {
156	        let Some(layer) = cfg.layers.get(layer_name) else {
157	            continue;
158	        };
159	        heap_total += u64::from(layer_heap_size(layer));
160	    }
