182	fn layer_heap_size(layer: &Layer) -> u32 {
183	    let mut total: u32 = 0;
184	    for seg in &layer.segments {
185	        if !matches!(seg.kind, SegmentKind::Heap) {
186	            continue;
187	        }
188	        if let Some(h) = seg.size.as_ref().and_then(SizeOrAuto::as_hex) {
189	            total = total.saturating_add(h.as_u32().unwrap_or(0));
190	        }
191	    }
192	    total
193	}
