//! Cross-field validation for `sw-launch.toml`, schema v1.2.
//!
//! Each rule has a stable error code (E0001..E0034). The full
//! catalogue is in `docs/design.md` "Validation rules". The codes
//! never change meaning; rules added later get new codes.
//!
//! `validate(&Config, scenario_name)` collects every diagnostic
//! before returning; callers decide whether to fail-fast or report
//! all. `cli::check` reports all and exits non-zero if any error-
//! severity diagnostic was emitted.
//!
//! Rules that require artifact sizes (overlap of byte ranges
//! resolved through listings) or vendor lockfile state (E0019
//! sidecar staleness) are stubbed at this step and re-enabled by
//! later steps as their infrastructure lands.

mod budgets;
mod diagnostic;
mod segments;
mod structural;

pub use diagnostic::{Diagnostic, Severity};

use crate::config::Config;
use crate::error::ErrorCode;

/// Validate a single scenario. Returns Ok if there are no errors;
/// always returns the full diagnostic list (warnings included)
/// in `Err` if any error severity was emitted.
pub fn validate(cfg: &Config, scenario_name: &str) -> Result<Vec<Diagnostic>, Vec<Diagnostic>> {
    let mut out = Vec::new();
    let scen = match cfg.scenarios.get(scenario_name) {
        Some(s) => s,
        None => {
            out.push(Diagnostic {
                code: ErrorCode(2),
                severity: Severity::Error,
                layer: None,
                segment: None,
                message: format!("scenario `{scenario_name}` not declared"),
                hint: None,
            });
            return Err(out);
        }
    };
    structural::check_scenario_structural(cfg, scenario_name, scen, &mut out);
    structural::check_layers(cfg, scen, &mut out);
    budgets::check_profile_resolution(cfg, scenario_name, scen, &mut out);
    segments::check_segment_shapes(cfg, scen, &mut out);
    budgets::check_oversized_heaps_need_justification(cfg, scen, &mut out);
    budgets::check_heap_budgets(cfg, scen, &mut out);
    budgets::check_total_rule_of_thumb(cfg, scen, &mut out);

    if out.iter().any(|d| d.severity == Severity::Error) {
        Err(out)
    } else {
        Ok(out)
    }
}

//! Structural rules E0001..E0009: scenario shape, layer
//! references, kind/load compatibility, UART size, halt
//! condition, patch target shape.

use super::diagnostic::{Diagnostic, err, err_with_hint, layer_err, layer_err_with_hint};
use crate::config::{Config, Layer, LoadMethod, Patch, Scenario};
use crate::error::ErrorCode;

pub(super) fn check_scenario_structural(
    cfg: &Config,
    scenario_name: &str,
    scen: &Scenario,
    out: &mut Vec<Diagnostic>,
) {
    if scen.layers.is_empty() {
        out.push(err(
            ErrorCode(1),
            format!("scenario `{scenario_name}` declares no layers"),
        ));
    }
    let run = scen.run.as_ref();
    let has_halt = run.and_then(|r| r.halt_on.as_ref()).is_some();
    let has_max = run.and_then(|r| r.max_cycles).is_some();
    if !has_halt && !has_max {
        out.push(err_with_hint(
            ErrorCode(8),
            format!("scenario `{scenario_name}` has no halt_on or max_cycles"),
            "set [scenarios.<name>.run].halt_on or .max_cycles".into(),
        ));
    }
    if !cfg.targets.contains_key(&scen.target) {
        out.push(err(
            ErrorCode(2),
            format!(
                "scenario `{scenario_name}` references undeclared target `{}`",
                scen.target
            ),
        ));
    }
}

pub(super) fn check_layers(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
    for name in &scen.layers {
        let Some(layer) = cfg.layers.get(name) else {
            out.push(err(
                ErrorCode(2),
                format!("scenario references undeclared layer `{name}`"),
            ));
            continue;
        };
        check_kind_load_compat(name, layer, out);
        check_uart_size(name, layer, out);
        check_patches(name, layer, out);
    }
}

fn check_kind_load_compat(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
    let Some(load) = &layer.load else { return };
    let kind = layer.kind.as_str();
    let bad_uart = matches!(
        kind,
        "assembler" | "binary" | "pcode" | "pcode-image" | "composite"
    ) && load.method == LoadMethod::Uart;
    if bad_uart {
        out.push(layer_err(
            ErrorCode(5),
            name,
            format!("kind `{kind}` cannot use load.method = \"uart\""),
        ));
    }
    if load.method == LoadMethod::Uart && load.max_bytes.is_none() {
        out.push(layer_err_with_hint(
            ErrorCode(4),
            name,
            "uart layer is missing load.max_bytes".into(),
            "set load.max_bytes = <hard cap>".into(),
        ));
    }
    if load.method == LoadMethod::Memory
        && load.address.is_none()
        && !layer.absolute_addresses
        && layer.segments.is_empty()
    {
        out.push(layer_err_with_hint(
            ErrorCode(15),
            name,
            "memory load with no address and no segments".into(),
            "set load.address or declare segments with claims".into(),
        ));
    }
}

fn check_uart_size(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
    let Some(load) = &layer.load else { return };
    if load.method != LoadMethod::Uart {
        return;
    }
    let Some(max_bytes) = load.max_bytes else {
        return;
    };
    if let Some(input) = &layer.input
        && let Ok(meta) = std::fs::metadata(input)
        && meta.len() > max_bytes
    {
        out.push(layer_err(
            ErrorCode(4),
            name,
            format!(
                "uart input `{input}` ({} bytes) exceeds max_bytes ({max_bytes})",
                meta.len()
            ),
        ));
    }
}

fn check_patches(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
    for p in &layer.patches {
        // Literal-hex target: verify it parses.
        if p.target.starts_with("0x") && crate::config::parse_hex_u32(&p.target).is_err() {
            out.push(layer_err(
                ErrorCode(6),
                name,
                format!("patch target `{}` is not a valid hex address", p.target),
            ));
        }
        // Cross-layer symbolic-target resolution lands in step 007.
        check_patch_value(name, p, out);
        check_patch_self_outside_segment(name, p, out);
    }
}

fn check_patch_value(name: &str, p: &Patch, out: &mut Vec<Diagnostic>) {
    let v = p.value.as_str();
    if v == "self.address" || v == "self.end" || v == "self.size" {
        // E0016 enforced separately.
        return;
    }
    if v.starts_with("0x") && crate::config::parse_hex_u32(v).is_err() {
        out.push(layer_err(
            ErrorCode(6),
            name,
            format!("patch value `{v}` is not a valid hex literal"),
        ));
    }
}

fn check_patch_self_outside_segment(name: &str, p: &Patch, out: &mut Vec<Diagnostic>) {
    let v = p.value.as_str();
    if v == "self.address" || v == "self.end" || v == "self.size" {
        out.push(layer_err_with_hint(
            ErrorCode(16),
            name,
            format!("patch value `{v}` only valid inside a segment block"),
            "move this patch into a [[layers.<n>.segments]] entry".into(),
        ));
    }
}

//! Segment shape rules E0011..E0016: SRAM/EBR/MMIO containment,
//! nonzero size, embedded vs reserved invariants.

use super::diagnostic::{Diagnostic, layer_seg_err, layer_seg_err_with_hint};
use crate::config::{Config, MemRange, Scenario, Segment, SegmentKind, SizeOrAuto, Target};
use crate::error::ErrorCode;

pub(super) fn check_segment_shapes(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
    let target = cfg.targets.get(&scen.target);
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        for seg in &layer.segments {
            check_segment_size(layer_name, seg, out);
            check_segment_embedded(layer_name, seg, out);
            check_segment_in_target_regions(layer_name, seg, target, out);
        }
    }
}

fn check_segment_size(layer_name: &str, seg: &Segment, out: &mut Vec<Diagnostic>) {
    if !matches!(
        seg.kind,
        SegmentKind::Stack | SegmentKind::Heap | SegmentKind::Bss
    ) {
        return;
    }
    let nonzero = match &seg.size {
        Some(SizeOrAuto::Hex(h)) if h.0 == "auto" => true,
        Some(SizeOrAuto::Hex(h)) => h.as_u32().map(|v| v > 0).unwrap_or(false),
        None => false,
    };
    if !nonzero {
        out.push(layer_seg_err(
            ErrorCode(13),
            layer_name,
            seg.name.as_deref(),
            "stack/heap/bss segment must have nonzero size".into(),
        ));
    }
}

fn check_segment_embedded(layer_name: &str, seg: &Segment, out: &mut Vec<Diagnostic>) {
    match seg.embedded {
        Some(true) => {
            if seg.symbol.is_none() {
                out.push(layer_seg_err_with_hint(
                    ErrorCode(14),
                    layer_name,
                    seg.name.as_deref(),
                    "embedded = true segment must declare `symbol`".into(),
                    "set symbol = \"<label-in-source>\"".into(),
                ));
            }
        }
        Some(false) => {
            let has_addr = seg.load.as_ref().and_then(|l| l.address.as_ref()).is_some();
            let has_claims = !seg.claims.is_empty();
            let has_size = seg.size.is_some();
            if !has_size {
                out.push(layer_seg_err_with_hint(
                    ErrorCode(15),
                    layer_name,
                    seg.name.as_deref(),
                    "embedded = false segment must declare `size`".into(),
                    "set size = \"0x...\"".into(),
                ));
            }
            if !has_addr && !has_claims {
                out.push(layer_seg_err_with_hint(
                    ErrorCode(15),
                    layer_name,
                    seg.name.as_deref(),
                    "embedded = false segment needs load.address or claims = [...]".into(),
                    "either set load.address or claim a (partition, region) cell".into(),
                ));
            }
        }
        None => {}
    }
}

fn check_segment_in_target_regions(
    layer_name: &str,
    seg: &Segment,
    target: Option<&Target>,
    out: &mut Vec<Diagnostic>,
) {
    let Some(target) = target else { return };
    let Some(load) = &seg.load else { return };
    let Some(addr_hex) = &load.address else {
        return;
    };
    let Ok(addr) = addr_hex.as_u32() else { return };
    let Some(end) = seg
        .size
        .as_ref()
        .and_then(SizeOrAuto::as_hex)
        .and_then(|h| h.as_u32().ok())
        .map(|sz| addr + sz)
    else {
        return;
    };

    let r = &target.regions;
    let in_sram = inside(addr, end, &r.sram);
    let touches_ebr = overlaps(addr, end, &r.ebr_stack);
    let touches_mmio = overlaps(addr, end, &r.mmio);
    if !in_sram || touches_ebr || touches_mmio {
        out.push(layer_seg_err(
            ErrorCode(11),
            layer_name,
            seg.name.as_deref(),
            format!(
                "segment range [0x{addr:06X}..0x{end:06X}) escapes SRAM or touches reserved regions"
            ),
        ));
    }
}

fn inside(addr: u32, end: u32, range: &MemRange) -> bool {
    let lo = range.start.as_u32().unwrap_or(0);
    let hi = range.end.as_u32().unwrap_or(0);
    addr >= lo && end <= hi.saturating_add(1)
}

fn overlaps(addr: u32, end: u32, range: &MemRange) -> bool {
    let lo = range.start.as_u32().unwrap_or(0);
    let hi = range.end.as_u32().unwrap_or(0);
    !(end <= lo || addr > hi)
}

