    assert_eq!(listing.resolve("eval_stack"), Some(0x0010));
    assert_eq!(listing.resolve("call_stack"), Some(0x0410));
    assert_eq!(listing.resolve("heap_seg"), Some(0x0C10));

    let mut by_layer = BTreeMap::new();
