#[test]
fn literal_hex_patches_resolve_in_address_order() {
    let toml = r#"
        schema_version = 1
        [project]
        name = "patches"
        [targets.cor24]
        kind = "emulator"
        word_bits = 24
        address_bits = 24
        endian = "big"
        loader = "cor24-memory-map"
        regions = { sram = { start = "0x000000", end = "0x0FFFFF" }, ebr_stack = { start = "0xFEEC00", end = "0xFEF7FF" }, mmio = { start = "0xFF0000", end = "0xFFFFFF" } }
        [scenarios.demo]
        target = "cor24"
        layers = ["a"]
        entry  = "0x000000"
        [scenarios.demo.run]
        max_cycles = 1
        [layers.a]
        kind = "binary"
        input = "a.bin"
