146	fn collect_layer(
147	    layer_name: &str,
148	    layer: &crate::config::Layer,
149	    artifacts: &Artifacts,
150	    scen: &Scenario,
151	    plan: &mut LoadPlan,
152	) -> Result<()> {
153	    if let Some(load) = &layer.load {
154	        match load.method {
155	            LoadMethod::Memory => {
156	                let Some(addr_hex) = &load.address else {
157	                    return Ok(());
158	                };
159	                let addr = addr_hex.as_u32()?;
160	                let path = artifacts
161	                    .by_layer
162	                    .get(layer_name)
163	                    .map(|a| a.artifact.clone())
164	                    .or_else(|| layer.input.as_deref().map(Utf8PathBuf::from))
165	                    .ok_or_else(|| {
166	                        Error::cli(format!("layer `{layer_name}` has no built artifact path"))
167	                    })?;
168	                plan.memory_loads.push(MemoryLoad {
169	                    layer: layer_name.into(),
170	                    path,
171	                    address: addr,
172	                });
173	            }
174	            LoadMethod::Uart => {
175	                let bytes = if let Some(input) = &layer.input {
176	                    std::fs::read(input).map_err(|source| Error::Io { source })?
177	                } else {
178	                    Vec::new()
179	                };
180	                let terminator = load.terminator.as_deref().and_then(terminator_byte);
181	                plan.uart.push(UartChunk {
182	                    layer: layer_name.into(),
183	                    bytes,
184	                    terminator,
185	                });
186	            }
187	        }
188	    }
189	    let _ = scen; // used by step 009 once profile-relative claims resolve
190	    for (idx, seg) in layer.segments.iter().enumerate() {
191	        if let Some(rs) = resolve_segment(layer_name, idx, seg, layer, artifacts) {
192	            plan.segments.push(rs);
193	        }
194	    }
195	    for p in &layer.patches {
196	        if let Some(rp) = resolve_patch(p, layer_name) {
197	            plan.patches.push(rp);
198	        }
199	    }
200	    Ok(())
201	}
202	
203	fn resolve_segment(
204	    layer_name: &str,
205	    idx: usize,
206	    seg: &crate::config::Segment,
207	    layer: &crate::config::Layer,
208	    artifacts: &Artifacts,
209	) -> Option<ResolvedSegment> {
210	    let size = seg
211	        .size
212	        .as_ref()
213	        .and_then(SizeOrAuto::as_hex)
214	        .and_then(|h| h.as_u32().ok())
215	        .unwrap_or(0);
216	    let start = if seg.embedded == Some(true) {
217	        let symbol = seg.symbol.as_deref()?;
218	        artifacts
219	            .by_layer
220	            .get(layer_name)?
221	            .listing
222	            .resolve(symbol)?
223	    } else {
224	        seg.load.as_ref()?.address.as_ref()?.as_u32().ok()?
225	    };

