/// Build the requested artifact. Hits the in-process cache if
/// the same inputs+args have been built already; otherwise
/// spawns the tool and records the result. argv shape is
/// dispatched on `self.kind`.
pub fn build(&mut self, job: &BuildJob) -> Result<BuildOutput> {
    let key = CacheKey {
        tool_path: self
            .tool_path
            .canonicalize_utf8()
            .unwrap_or_else(|_| self.tool_path.clone())
            .to_string(),
        input_sha: hash_file_sha256(&job.input)?,
        args: job.extra_args.clone(),
    };
    if let Some(cached) = self.cache.get(&key) {
        return Ok(cached.clone());
    }
    for p in [job.output_bin.parent(), job.output_lst.parent()]
        .into_iter()
        .flatten()
    {
        std::fs::create_dir_all(p).map_err(|source| Error::Io { source })?;
    }
    let mut cmd = Command::new(self.tool_path.as_std_path());
    let in_p = job.input.as_std_path();
    let out_p = job.output_bin.as_std_path();
    match self.kind {
        ToolKind::Assembler => {
            cmd.args(["--assemble".as_ref(), in_p, out_p, job.output_lst.as_std_path()]);
        }
        ToolKind::Pcode => {
            cmd.args([in_p, "-o".as_ref(), out_p]);
        }
    }
    cmd.args(&job.extra_args);
    let output = cmd.output().map_err(|source| Error::Io { source })?;
    self.spawn_count += 1;
    if !output.status.success() {
        return Err(Error::cli(format!(
            "{} exited with {}: {}",
            self.tool_path,
            output.status,
            String::from_utf8_lossy(&output.stderr)
        )));
    }
    let out = BuildOutput {
        artifact: job.output_bin.clone(),
        listing: match self.kind {
            ToolKind::Assembler => job.output_lst.clone(),
            ToolKind::Pcode => Utf8PathBuf::new(),
        },
        stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
        stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
    };

