82	impl LoadPlan {
83	    /// Construct a `LoadPlan` from a config + scenario name +
84	    /// already-built artifacts. Returns `Err` only on shape
85	    /// problems that validation should have caught earlier
86	    /// (missing scenario, missing artifact for a memory layer,
87	    /// unparseable hex).
88	    pub fn build(cfg: &Config, scenario_name: &str, artifacts: &Artifacts) -> Result<LoadPlan> {
89	        let scen = cfg
90	            .scenarios
91	            .get(scenario_name)
92	            .ok_or_else(|| Error::cli(format!("scenario `{scenario_name}` not declared")))?;
93	        let mut plan = LoadPlan {
94	            entry: scen.entry.as_u32()?,
95	            ..LoadPlan::default()
96	        };
97	        // Pass 1: memory loads, UART, segments. No patches yet --
98	        // cross-layer patches need every layer's load.address known.
99	        for layer_name in &scen.layers {
100	            let Some(layer) = cfg.layers.get(layer_name) else {
101	                continue;
102	            };
103	            collect_layer(layer_name, layer, artifacts, scen, &mut plan)?;
104	        }
105	        plan.memory_loads.sort_by_key(|m| m.address);
106	        // Pass 2: resolve patches now that the plan knows where
107	        // every layer ended up. Literal-hex stays inline; cross-
108	        // layer "<other>.<symbol>" looks up the producing layer's
109	        // listing in `artifacts`.
110	        for layer_name in &scen.layers {
111	            let Some(layer) = cfg.layers.get(layer_name) else {
112	                continue;
113	            };
114	            for p in &layer.patches {
115	                if let Some(rp) = resolve_patch(p, layer_name, cfg, artifacts, &plan)? {
116	                    plan.patches.push(rp);
117	                }
118	            }
119	        }
120	        plan.patches.sort_by_key(|p| p.address);
121	        Ok(plan)
122	    }
