124	    /// Translate this plan into the argv `cor24-run` expects,
125	    /// without spawning anything. Used by step 009 (runner) and
126	    /// by the snapshot tests below.
127	    pub fn cor24_argv(&self) -> Vec<String> {
128	        let mut argv: Vec<String> = Vec::new();
129	        for m in &self.memory_loads {
130	            argv.push("--load-binary".into());
131	            argv.push(format!(
132	                "{path}@0x{addr:06X}",
133	                path = m.path,
134	                addr = m.address
135	            ));
136	        }
137	        for p in &self.patches {
138	            argv.push("--patch".into());
139	            argv.push(format!(
140	                "0x{addr:06X}=0x{value:06X}",
141	                addr = p.address,
142	                value = p.value
143	            ));
144	        }
145	        argv.push("--entry".into());
146	        argv.push(format!("0x{:06X}", self.entry));
147	        if !self.uart.is_empty() {
148	            let mut payload: Vec<u8> = Vec::new();
149	            for chunk in &self.uart {
150	                payload.extend_from_slice(&chunk.bytes);
151	                if let Some(t) = chunk.terminator {
152	                    payload.push(t);
153	                }
154	            }
155	            argv.push("--uart-input".into());
156	            argv.push(String::from_utf8_lossy(&payload).into_owned());
157	        }
158	        argv
159	    }
160	}
